message.content:
{
  "definition_simple": "力が同じくらいで、どちらが勝つかわからない激しい戦い。",
  "definition_standard": "互いに力が接近していて、勝敗の判定がつきにくいきわどい戦い。また、接近して激しく戦うこと。",
  "pos": "名詞・サ変名詞",
  "semantic_class": "action",
  "sentences": [
    {
      "text": "昨日の野球の試合は、最後まで接戦だった。",
      "tier": "T1"
    },
    {
      "text": "今回の市長選挙は、まれに見る接戦となっている。",
      "tier": "T2"
    },
    {
      "text": "両チームは延長戦に突入するほどの接戦を演じた。",
      "tier": "T3"
    },
    {
      "text": "手に汗握る接戦の末、我が校が辛くも勝利を収めた。",
      "tier": "T3"
    },
    {
      "text": "ライバル同士の接戦を制して、彼は見事に優勝を果たした。",
      "tier": "T4"
    },
    {
      "text": "世論調査では接戦が予想されていたが、開票後は意外な展開となった。",
      "tier": "T4"
    },
    {
      "text": "前半から激しい接戦が繰り広げられ、観客席は大いに沸いた。",
      "tier": "T5"
    },
    {
      "text": "新旧王者が互いの意地をかけて接戦を展開し、会場の熱気は最高潮に達した。",
      "tier": "T5"
    },
    {
      "text": "両候補の政策支持率は拮抗しており、投開票日直前まで予断を許さない接戦が続いた。",
      "tier": "T6"
    },
    {
      "text": "世界市場でシェアを争う両社の開発競争は、まさに威信をかけた接戦の様相を呈している。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [
    {
      "form": "接戦した",
      "label": "past"
    },
    {
      "form": "接戦している",
      "label": "progressive"
    }
  ],
  "morphology_wrong_forms": [
    {
      "target_form": "接戦した",
      "wrong_form": "接戦った",
      "explanation": "サ変動詞の語幹を五段動詞と誤認して促音便化させてしまっている。"
    },
    {
      "target_form": "接戦した",
      "wrong_form": "接戦れた",
      "explanation": "一段動詞の過去形活用語尾「〜れた」を誤って名詞語幹に直接接続している。"
    },
    {
      "target_form": "接戦した",
      "wrong_form": "接戦だ",
      "explanation": "動詞の過去形を作ろうとして、形容動詞（ダ列）の過去形「だった」の短縮形と混同している。"
    },
    {
      "target_form": "接戦している",
      "wrong_form": "接戦っている",
      "explanation": "五段動詞のテ形（促音便）に「いる」をつけて進行形を作ろうとした誤用。"
    },
    {
      "target_form": "接戦している",
      "wrong_form": "接戦中ている",
      "explanation": "状態を示す名詞接尾辞「〜中」に直接動詞語尾「ている」を接続してしまっている。"
    },
    {
      "target_form": "接戦している",
      "wrong_form": "接戦ある",
      "explanation": "進行・継続状態を表す補助動詞「いる」ではなく存在動詞「ある」を誤って選択している。"
    }
  ],
  "primary_collocate": "接戦を制する",
  "collocation_distractors": [
    {
      "word": "接戦を勝つ",
      "explanation": "日本語では「接戦で勝つ」と格助詞「で」を用いるのが自然であり、「接戦を勝つ」とは言わない。"
    },
    {
      "word": "接戦を競う",
      "explanation": "「接戦」そのものに争い・競争の意味が含まれるため、動詞「競う」を重ねるのは意味の重複となり不自然である。"
    },
    {
      "word": "接戦を破る",
      "explanation": "「均衡を破る」や「相手を破る」とは言うが、戦況そのものを対象として「接戦を破る」というコロケーションは存在しない。"
    }
  ],
  "collocation_wrong_collocate": "接戦を収める",
  "cloze_distractors": [
    {
      "word": "乱戦",
      "explanation": "「乱戦」は入り乱れて秩序のない激しい戦いを指し、実力が拮抗した競り合いを表す文脈には合わない。"
    },
    {
      "word": "合戦",
      "explanation": "「合戦」は歴史的な武力衝突や伝統的な勝負を指す古風な語であり、現代のスポーツの試合に対して不自然。"
    },
    {
      "word": "観戦",
      "explanation": "「観戦」は試合を見物することを意味するため、選手自身が競い合って勝利を収める主客関係と矛盾する。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は自己記録を更新するため、トラックで一人で接戦した。",
      "reason": "「接戦」は複数の対戦相手の実力が伯仲して競り合う状況を指すため、単独の活動に対して使えない。"
    },
    {
      "sentence": "圧倒的な戦力差があり、序盤から10点差をつけた接戦となった。",
      "reason": "「接戦」は点差や実力差がわずかで勝敗が際どい勝負を意味するため、「大差」「圧倒的」という状況と意味的に矛盾する。"
    },
    {
      "sentence": "来週の土曜日に、両校の間で接戦が予定されている。",
      "reason": "「接戦」は試合の展開や結果として現れる性質・状態であり、「定期戦」や「練習試合」のように事前に予定・計画できるイベント名詞ではない。"
    }
  ],
  "spot_incorrect": {
    "sentence": "両チームの実力差が大きく、最後まで接戦となって大差で試合が終わった。",
    "error_description": "実力差が大きく大差で決着する展開は「接戦（競り合い）」の意味と完全に矛盾している。",
    "corrected_sentence": "両チームの実力差が大きく、最後まで一方的な展開となって大差で試合が終わった。"
  },
  "word_family_forms": [
    "接戦する"
  ],
  "word_family_fake_forms": [
    "接戦的",
    "接戦さ",
    "接戦化"
  ],
  "syn_ant_candidates": [
    {
      "candidate": "激戦",
      "type": "synonym"
    },
    {
      "candidate": "好勝負",
      "type": "synonym"
    },
    {
      "candidate": "圧勝",
      "type": "antonym"
    },
    {
      "candidate": "ワンサイドゲーム",
      "type": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "の",
      "is_correct": true,
      "explanation": "名詞「接戦」と名詞「末」をつなぎ、「接戦という戦いの結末」を表す連体修飾の格助詞として正しい。"
    },
    {
      "particle": "に",
      "is_correct": false,
      "explanation": "「接戦に末」と名詞同士を直接「に」で接続して時間的・状況的な帰着点を作る用法は文法的に誤り。"
    },
    {
      "particle": "を",
      "is_correct": false,
      "explanation": "目的語を示す格助詞「を」は後続の動詞を修飾するものであり、名詞「末」に直接接続することはできない。"
    },
    {
      "particle": "で",
      "is_correct": false,
      "explanation": "「接戦で勝つ」のように述語にかかる手段・状況なら可能だが、名詞「末」に連体修飾として接続することはできない。"
    }
  ]
}
